+package com.example;
+
+import com.example.MessageStore.ContactMessage;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+import java.util.regex.Pattern;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+    private final MessageStore store;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>();
+    private boolean sentNeedsEdit;
+
+    public ContactView(MessageStore store) {
+        this.store = store;
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+        message.setMaxLength(500);
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+        grid.setItems(store.all());
+        send.addClickListener(event -> submit());
+        add(name, email, phone, message, send, grid);
+        addClickListenersToEnableSend();
+        whenAttached(ui -> ui.addShortcutListener((com.vaadin.flow.server.Command) this::submit, Key.ENTER));
+    }
+
+    private void addClickListenersToEnableSend() {
+        name.addValueChangeListener(e -> edited());
+        email.addValueChangeListener(e -> edited());
+        phone.addValueChangeListener(e -> edited());
+        message.addValueChangeListener(e -> edited());
+    }
+
+    private void edited() {
+        clearErrors();
+        if (sentNeedsEdit) { sentNeedsEdit = false; send.setEnabled(true); }
+    }
+
+    private void clearErrors() {
+        name.setInvalid(false); name.setErrorMessage(null);
+        email.setInvalid(false); email.setErrorMessage(null);
+        message.setInvalid(false); message.setErrorMessage(null);
+    }
+
+    private void submit() {
+        clearErrors();
+        boolean valid = true;
+        String n = value(name), e = value(email), p = value(phone), m = value(message);
+        if (n.isBlank()) { name.setErrorMessage("Name is required"); name.setInvalid(true); valid = false; }
+        if (!e.isBlank() && !EMAIL.matcher(e).matches()) { email.setErrorMessage("Enter a valid e-mail address"); email.setInvalid(true); valid = false; }
+        if (e.isBlank() && p.isBlank()) { email.setErrorMessage("Give an e-mail address or a phone number"); email.setInvalid(true); valid = false; }
+        if (m.isBlank()) { message.setErrorMessage("Message is required"); message.setInvalid(true); valid = false; }
+        if (m.length() > 500) { message.setErrorMessage("Message must be at most 500 characters"); message.setInvalid(true); valid = false; }
+        if (!valid) return;
+        store.add(new ContactMessage(n, e, p, m));
+        grid.setItems(store.all());
+        Notification.show("Message sent");
+        name.clear(); email.clear(); phone.clear(); message.clear();
+        sentNeedsEdit = true;
+        send.setEnabled(false);
+    }
+
+    private String value(TextField field) { return field.getValue() == null ? "" : field.getValue(); }
+    private String value(EmailField field) { return field.getValue() == null ? "" : field.getValue(); }
+    private String value(TextArea field) { return field.getValue() == null ? "" : field.getValue(); }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (value(name).isEmpty() && value(email).isEmpty() && value(phone).isEmpty() && value(message).isEmpty()) return;
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.add("You have an unsent message. Discard it?");
+        Button keep = new Button("Keep editing", e -> dialog.close());
+        Button discard = new Button("Discard", e -> { dialog.close(); action.proceed(); });
+        dialog.add(keep, discard);
+        dialog.open();
+    }
+}
